select customer_id, round((100 * sum(case when status = 'EXPIRED' then 1 else 0 end)) / count(*), 1) pct_expired, count(case when status = 'ACTIVE' then 1 end) active_count from subscriptions where customer_id = 20 and monthly_fee > 130 group by customer_id order by customer_id desc, active_count desc;
